"use server";

// Generated by philote from component HorsePicker's picks. Do not edit.
import { cookies } from "next/headers";
import { redirect } from "next/navigation";

import { viewerCookie } from "@/lib/viewer";

// pick makes a Horse the viewer for a year, then opens /swipe.
export async function pick(id: string): Promise<void> {
    (await cookies()).set(viewerCookie, id, {
        path: "/",
        httpOnly: true,
        sameSite: "lax",
        maxAge: 60 * 60 * 24 * 365,
    });
    redirect("/swipe");
}
